#include <stdio.h>
int main() {
    char s[1005]; if (scanf("%s", s) != 1) return 0;
    int first = 1;
    for (int i = 0; s[i]; i++) {
        if ((s[i] - '0') % 2 != 0) {
            if (!first) putchar(' ');
            putchar(s[i]); first = 0;
        }
    }
    for (int i = 0; s[i]; i++) {
        if ((s[i] - '0') % 2 == 0) {
            if (!first) putchar(' ');
            putchar(s[i]); first = 0;
        }
    }
    putchar('\n');
    return 0;
}

