#include <iostream>
#include <string>
using namespace std;
int main() {
    string s; if (!(cin >> s)) return 0;
    bool first = true;
    for (char c : s) if ((c - '0') % 2 != 0) { if (!first) cout << " "; cout << c; first = false; }
    for (char c : s) if ((c - '0') % 2 == 0) { if (!first) cout << " "; cout << c; first = false; }
    cout << "\n";
    return 0;
}

