const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (!toks || !toks[0]) return;
    const s = toks[0];
    const odds = s.split("").filter(c => parseInt(c, 10) % 2 !== 0);
    const evens = s.split("").filter(c => parseInt(c, 10) % 2 === 0);
    console.log(odds.concat(evens).join(" "));
}
main();

